Read file D:\Github\dsai-ap1-EstiloMarcado\src\frontend\src\app\periodo-agenda.ts, lines 1-21
1: export interface FaixaAgenda { de: string; ate: string }
2: 
3: /** A listagem aceita no máximo 31 dias por consulta, com ambas as pontas inclusivas. */
4: export function dividirPeriodoAgenda(de: string, ate: string): FaixaAgenda[] {
5:   if (!/^\d{4}-\d{2}-\d{2}$/.test(de) || !/^\d{4}-\d{2}-\d{2}$/.test(ate) || de > ate) {
6:     return [];
7:   }
8:   const faixas: FaixaAgenda[] = [];
9:   let inicio = de;
10:   while (inicio <= ate) {
11:     const fim = new Date(`${inicio}T12:00:00Z`);
12:     fim.setUTCDate(fim.getUTCDate() + 30);
13:     const limite = fim.toISOString().slice(0, 10);
14:     const ultimo = limite < ate ? limite : ate;
15:     faixas.push({ de: inicio, ate: ultimo });
16:     if (ultimo === ate) break;
17:     fim.setUTCDate(fim.getUTCDate() + 1);
18:     inicio = fim.toISOString().slice(0, 10);
19:   }
20:   return faixas;
21: }

