91:     if (profissionalId) { params['profissionalId'] = String(profissionalId); }
92:     return this.http.get<Relatorio>(`/api/unidades/${unidadeId}/relatorios/operacionais`,
93:       { params });
94:   }
95:   private mutar<T>(acao: () => Observable<T>): Observable<T> {
96:     return this.http.get('/api/autenticacao/csrf').pipe(switchMap(() => acao()));
97:   }
