163: export class ListaEsperaComponent {
164:   readonly dataLocal = dataLocal;
165:   readonly dataHoraLocal = dataHoraLocal;
166:   readonly instanteLocal = instanteLocal;
167:   private readonly api = inject(OperacaoApi);
168:   private readonly catalogo = inject(EstabelecimentoService);
169:   private readonly rota = inject(ActivatedRoute);
170:   readonly solicitacoes = signal<Solicitacao[]>([]);
171:   readonly ofertas = signal<Oferta[]>([]);
172:   readonly filiais = signal<{ id: number; nome: string }[]>([]);
173:   readonly servicos = signal<ServicoPublico[]>([]);
174:   readonly profissionais = signal<{ id: number; nome: string }[]>([]);
175:   readonly mensagem = signal('');
176:   readonly erro = signal('');
177:   readonly ocupado = signal(false);
178:   unidadeId: number | null = null;
179:   servicoId: number | null = null;
180:   profissionalId: number | null = null;
181:   dataInicio = '';
182:   dataFim = '';
183:   horaInicio = '';
184:   horaFim = '';
185:   constructor() {
186:     const params = this.rota.snapshot.queryParamMap;
187:     const unidade = Number(params.get('unidadeId') ??
188:       (typeof localStorage === 'undefined' ? null : localStorage.getItem('estilo-marcado-filial')));
189:     const servico = Number(params.get('servicoId'));
190:     const profissional = Number(params.get('profissionalId'));
191:     this.unidadeId = unidade > 0 ? unidade : null;
192:     this.servicoId = servico > 0 ? servico : null;
193:     this.profissionalId = profissional > 0 ? profissional : null;
194:     this.dataInicio = params.get('dataInicio') ?? '';
195:     this.dataFim = this.dataInicio;
196:     this.carregarFiliais();
197:     if (this.unidadeId) { this.trocarFilial(); }
198:     this.carregar();
199:   }
200: 
201:   private carregarFiliais(): void {
202:     const opcoes = new Map<number, string>();
203:     const aplicar = () => this.filiais.set(
204:       [...opcoes].map(([id, nome]) => ({ id, nome })).sort((a, b) => a.nome.localeCompare(b.nome)));
205:     if (this.unidadeId) {
206:       this.catalogo.filialPublica(this.unidadeId).subscribe({
207:         next: filial => { opcoes.set(filial.id, filial.nome); aplicar(); }, error: () => { }
208:       });
209:     }
210:     this.api.minhasFiliais().subscribe({
211:       next: lista => { lista.forEach(filial => opcoes.set(filial.id, filial.nome)); aplicar(); },
212:       error: () => { }
213:     });
214:   }
215: 
216:   trocarFilial(): void {
217:     this.servicos.set([]);
218:     this.profissionais.set([]);
219:     if (!this.unidadeId) { this.servicoId = null; this.profissionalId = null; return; }
220:     const desejado = this.servicoId;
221:     this.catalogo.servicosDisponiveis(this.unidadeId).subscribe({
222:       next: dados => {
223:         this.servicos.set(dados);
224:         this.servicoId = dados.some(s => s.id === desejado) ? desejado : (dados[0]?.id ?? null);
225:         this.trocarServico();
226:       },
227:       error: () => this.erro.set('Não foi possível carregar os serviços desta filial.')
228:     });
229:   }
230: 
231:   trocarServico(): void {
232:     this.profissionalId = null;
233:     const servico = this.servicos().find(item => item.id === this.servicoId);
234:     this.profissionais.set(servico?.profissionais ?? []);
235:   }
236:   carregar(): void { this.api.privadas().subscribe({ next: dados => this.solicitacoes.set(dados),
237:     error: () => this.erro.set('Não foi possível carregar a lista.') }); }
238:   entrar(): void {
239:     if (!this.unidadeId || !this.servicoId) { this.erro.set('Informe filial e serviço.'); return; }
240:     this.ocupado.set(true); this.erro.set('');
241:     this.api.entrar(this.unidadeId, { servicoId: this.servicoId, profissionalId: this.profissionalId,
242:       dataInicio: this.dataInicio, dataFim: this.dataFim,
243:       horaInicio: this.horaInicio || null, horaFim: this.horaFim || null }).subscribe({
244:       next: () => { this.ocupado.set(false); this.mensagem.set('Preferência salva.'); this.carregar(); },
245:       error: () => { this.ocupado.set(false); this.erro.set('Verifique datas, serviço e filial.'); }
246:     });
247:   }
248:   cancelar(id: number): void {
249:     this.api.cancelar(id).subscribe({ next: () => this.carregar(),
250:       error: () => this.erro.set('Não foi possível cancelar a solicitação.') });
251:   }
252:   verOfertas(id: number): void {
253:     this.api.ofertas(id).subscribe({ next: ofertas => this.ofertas.set(ofertas),
254:       error: () => this.erro.set('Não foi possível carregar ofertas.') });
255:   }
256:   aceitar(oferta: Oferta): void {
257:     this.api.aceitar(oferta.solicitacaoId, oferta.id).subscribe({
258:       next: () => { this.mensagem.set('Agendamento realizado. Confira seus agendamentos.'); this.carregar();
259:         this.verOfertas(oferta.solicitacaoId); },
260:       error: () => { this.erro.set('A vaga não está mais disponível. Suas preferências foram preservadas.');
261:         this.verOfertas(oferta.solicitacaoId); this.carregar(); }
262:     });
263:   }
264: }
