455:   profissionalId: number | null = null; dataEncaixe = ''; inicio = '';
456:   autorizada = false; statusFiltro = 'ATIVA';
457:   private consultaAtual = 0;
458:   constructor() { this.carregar(); }
459:   carregar(): void { const id = this.auth.sessao()?.unidadeId;
