export type EstadoLista = 'carregando' | 'erro' | 'sem-dados' | 'sem-resultado' | 'conteudo';

export interface SnapshotLista {
  carregando: boolean;
  erro: boolean;
  total: number;
  filtrosAtivos: number;
}

export function classificarLista(s: SnapshotLista): EstadoLista {
  if (s.erro) return 'erro';
  if (s.carregando) return 'carregando';
  if (s.total > 0) return 'conteudo';
  return s.filtrosAtivos > 0 ? 'sem-resultado' : 'sem-dados';
}
