export interface OpcaoFiltro { id: number; rotulo: string }
export interface FiltroAtivo { chave: string; rotulo: string; valor: string }

/** Aceita apenas identificadores inteiros positivos. */
export function idUrlValido(valor: string | null | undefined): number | null {
  if (!valor || !/^[1-9]\d*$/.test(valor)) return null;
  const id = Number(valor);
  return Number.isSafeInteger(id) ? id : null;
}

/** Só aceita uma seleção se o identificador existir entre as opções visíveis ao perfil. */
export function selecaoValida(valor: string | null | undefined,
                               opcoes: readonly { id: number }[]): number | null {
  const id = idUrlValido(valor);
  return id !== null && opcoes.some(o => o.id === id) ? id : null;
}

export function resumoFiltros(filtros: readonly FiltroAtivo[]): string {
  return filtros.map(f => `${f.rotulo}: ${f.valor}`).join(' · ');
}

export function parametrosFiltrosUrl(filtros: Record<string, string | number | null | undefined>):
    Record<string, string> {
  const params: Record<string, string> = {};
  for (const [chave, valor] of Object.entries(filtros)) {
    if (valor === null || valor === undefined || valor === '') continue;
    params[chave] = String(valor);
  }
  return params;
}
